/**
 * A policy's cap is consumed cumulatively: each payout draws down what remains,
 * and a claim can never pay out more than is left. The clamp is applied AFTER
 * rounding, so a fractional payout cannot round its way past the remaining cap.
 *
 * Takes the policy's items rather than looking them up, so that the caller —
 * which must resolve the same items to seed the cap — resolves them once.
 */
const settleClaim = (
  incident: Incident,
  policyItems: Item[],
  remainingBefore: number,
): ClaimResult => {
  const desired = roundPayoutDown(payoutBeforeRounding(incident, policyItems));
  const payout = Math.min(desired, remainingBefore);
  return { payout, remainingCap: remainingBefore - payout };
};

/**
 * Tracks what each policy has left of its cap as claims land against it. A
 * policy is seeded from its items the first time it is claimed against, which
 * is why this needs the scenario: the cap is a property of the covered items,
 * and those live in the quote step the claim points at.
 */
const capLedger = (scenario: Scenario) => {
  const remainingByPolicy = new Map<number, number>();

  return {
    remainingFor: (policy: number): number =>
      remainingByPolicy.get(policy) ??
      capFor(itemsCoveredBy(policy, scenario)),
    record: (policy: number, remaining: number): void => {
      remainingByPolicy.set(policy, remaining);
    },
  };
};

/**
 * Steps are processed in order because claims draw down a policy's remaining
 * cap, so each result depends on the claims before it.
 */
export const runScenario = (scenario: Scenario): ScenarioResult => {
  const caps = capLedger(scenario);

  const results = scenario.steps.map((step, precedingSteps) => {
    if (step.op !== "claim") {
      return {
        premium: quotePremium(
          step.items ?? [],
          scenario.customer,
          precedingSteps,
        ),
      };
    }

    const policy = step.policy ?? 0;
    // Non-null: only claim steps reach here, and every claim carries an
    // incident. See the Step doc comment.
    const result = settleClaim(
      step.incident!,
      itemsCoveredBy(policy, scenario),
      caps.remainingFor(policy),
    );
    caps.record(policy, result.remainingCap);
    return result;
  });

  return { results };
};
